import{_ as s,o as i,a as t,a2 as a}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Search Engines","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/search-engines.md","filePath":"advanced/search-engines.md","lastUpdated":1789319767000}'),n={name:"advanced/search-engines.md"};function d(o,e,c,r,h,l){return i(),t("div",null,e[0]||(e[0]=[a(`<h1 id="search-engines" tabindex="-1">Search Engines <a class="header-anchor" href="#search-engines" aria-label="Permalink to &quot;Search Engines&quot;">​</a></h1><p>Product search on the storefront, in the admin product grid and in the catalog API is routed through one manager that picks an <strong>engine</strong> per <strong>context</strong>. The database engine is always available; Elasticsearch is the alternative. This page describes the pieces a developer meets: the manager, the contracts, the configuration keys and the indexing jobs. Installing and pointing Bagisto at an Elasticsearch cluster is on <a href="./../performance/configure-elasticsearch.html">Configure Elasticsearch</a>.</p><div class="info custom-block"><p class="custom-block-title">Two implementations</p><p>The current development version has the engine-agnostic design described here (<code>Webkul\\Product\\Services\\Search</code>). <strong>Bagisto 2.4</strong> reaches Elasticsearch through <code>Webkul\\Product\\Repositories\\ElasticSearchRepository</code>, chooses the engine per call with <code>ProductRepository::setSearchEngine(&#39;elastic&#39;)</code>, and keeps its settings under <code>catalog.products.search</code> in the admin plus the <code>.env</code> file for the connection. The differences are called out below.</p></div><h2 id="how-a-query-is-routed" tabindex="-1">How a query is routed <a class="header-anchor" href="#how-a-query-is-routed" aria-label="Permalink to &quot;How a query is routed&quot;">​</a></h2><p><code>Webkul\\Product\\Services\\Search\\SearchEngineManager</code> holds the decision:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ENABLED_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;search_engines.general.settings.enabled&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ENGINE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;search_engines.general.settings.engine&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ADMIN_MODE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;search_engines.general.products.admin_mode&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> STOREFRONT_MODE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;search_engines.general.products.storefront_mode&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ol><li>If the master switch is off, every context uses the database.</li><li>Otherwise the master engine is read (<code>database</code> or <code>elastic</code>).</li><li>A context may override it: <code>admin_mode</code> for the admin product grid and product search, <code>storefront_mode</code> for category pages, the search page and the storefront product API. An empty value means &quot;use the default engine&quot;.</li></ol><p>The two contexts are the cases of <code>Webkul\\Product\\Enums\\SearchContextEnum</code> (<code>STOREFRONT</code>, <code>ADMIN</code>). A caller sets the context on the repository, and everything downstream resolves the engine from it:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">productRepository</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setSearchContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SearchContextEnum</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">STOREFRONT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getAll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($params);</span></span></code></pre></div><p><code>ProductRepository::getAll()</code> then either queries the database or calls <code>SearchEngine::search()</code> for ids and loads those. <code>findBySlug()</code> asks the engine first and falls back to the <code>url_key</code> attribute.</p><h2 id="contracts-and-bindings" tabindex="-1">Contracts and bindings <a class="header-anchor" href="#contracts-and-bindings" aria-label="Permalink to &quot;Contracts and bindings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contract</th><th>Methods</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Webkul\\Product\\Contracts\\SearchEngine</code></td><td><code>search(array $params, array $options): array{ids, total}</code>, <code>getSuggestions(?string $query): ?string</code>, <code>getMaxPrice(array $params = []): float</code>, <code>findBySlug(string $slug): ?int</code></td><td>Answers queries</td></tr><tr><td><code>Webkul\\Product\\Contracts\\SearchIndexer</code></td><td><code>indexBatch(array $products)</code>, <code>deleteBatch(array $productIds)</code>, <code>reindexFull()</code></td><td>Keeps the engine&#39;s index in step with the catalog</td></tr><tr><td><code>Webkul\\Product\\Contracts\\SearchEngineConnection</code></td><td><code>configure(array $overrides = [])</code>, <code>probe(array $overrides = [])</code>, <code>describesRecorded(array $overrides): bool</code></td><td>Applies stored settings and tests reachability</td></tr></tbody></table><p><code>ProductServiceProvider</code> binds the implementations under conventional container names:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;product.search.connection.elastic&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ElasticConnection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;product.search.engine.database&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DatabaseEngine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;product.search.engine.elastic&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ElasticSearchEngine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">singleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;product.search.indexer.elastic&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ElasticSearchIndexer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The manager resolves <code>product.search.engine.{value}</code> and <code>product.search.indexer.{value}</code> where <code>{value}</code> is a case of <code>Webkul\\Product\\Enums\\SearchEngineEnum</code> (<code>database</code>, <code>elastic</code>). When no external engine is enabled the indexer is <code>NullIndexer</code>, so indexing jobs are safe to dispatch unconditionally.</p><p><code>DatabaseEngine</code> is deliberately partial: <code>search()</code> returns no ids and <code>findBySlug()</code> returns <code>null</code>, because with the database engine the repository queries products directly; only <code>getMaxPrice()</code> does real work.</p><div class="warning custom-block"><p class="custom-block-title">Adding a third engine means editing core</p><p>The engine list is a closed enum. <code>SearchEngineOptions::getEngineOptions()</code> iterates <code>SearchEngineEnum::cases()</code> and the manager type-hints the enum, so a Meilisearch or OpenSearch engine cannot be registered from a package by binding <code>product.search.engine.meilisearch</code> alone; a new enum case is needed. The bindings are documented here so that an override of the Elasticsearch engine, or a fork adding a case, knows where to hook in.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>All settings are in the <strong>Search Engines</strong> configuration group, stored in <code>core_config</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>search_engines.general.settings.enabled</code></td><td>Master switch; off means database everywhere</td></tr><tr><td><code>search_engines.general.settings.engine</code></td><td><code>database</code> or <code>elastic</code></td></tr><tr><td><code>search_engines.general.products.admin_mode</code></td><td>Engine for the admin context, or empty to inherit</td></tr><tr><td><code>search_engines.general.products.storefront_mode</code></td><td>Engine for the storefront context, or empty to inherit</td></tr><tr><td><code>search_engines.elastic.settings.auth_type</code></td><td><code>none</code>, <code>basic</code>, <code>api_key</code>, <code>cloud_api_key</code>, <code>cloud_basic</code></td></tr><tr><td><code>search_engines.elastic.settings.hosts</code></td><td>Comma-separated host list</td></tr><tr><td><code>search_engines.elastic.settings.cloud_id</code></td><td>Elastic Cloud id</td></tr><tr><td><code>search_engines.elastic.settings.username</code>, <code>password</code>, <code>api_key</code></td><td>Credentials, shown according to <code>auth_type</code></td></tr><tr><td><code>search_engines.elastic.settings.index_prefix</code></td><td>Prefixed to every index name so several stores can share a cluster</td></tr><tr><td><code>search_engines.elastic.settings.min_query_length</code>, <code>max_query_length</code></td><td>Query length bounds (defaults 0 and 1000)</td></tr></tbody></table><p><code>Webkul\\Product\\Enums\\ElasticAuthEnum</code> maps each auth type to the <code>elasticsearch.connections.*</code> entry it configures (<code>default</code>, <code>api</code> or <code>cloud</code>) and to the settings it reads; the <code>depends</code> rules on the admin fields are generated from it.</p><p>At boot, <code>SearchEngineConfigurator</code> calls <code>ElasticConnection::configure()</code>, which copies the stored settings onto <code>config/elasticsearch.php</code> and clears credentials the chosen auth type does not use. A setting left empty keeps the value from <code>.env</code> (<code>ELASTICSEARCH_HOST</code>, <code>ELASTICSEARCH_USER</code>, <code>ELASTICSEARCH_PASS</code>, <code>ELASTICSEARCH_API_KEY</code>, <code>ELASTICSEARCH_CLOUD_ID</code>, <code>ELASTICSEARCH_INDEX_PREFIX</code>), so a deployment can still keep credentials out of the database.</p><p>The migration <code>2026_08_27_000001_move_search_engine_config_codes</code> carries the five 2.4 keys under <code>catalog.products.search</code> over to the new names and switches <code>enabled</code> on wherever an external engine had been chosen; the connection settings themselves are not migrated from <code>.env</code>.</p><h3 id="connection-test" tabindex="-1">Connection test <a class="header-anchor" href="#connection-test" aria-label="Permalink to &quot;Connection test&quot;">​</a></h3><p><code>POST admin/configuration/search-engines/{engine}/test-connection</code> (<code>admin.configuration.search-engines.test-connection</code>) probes the engine with the settings currently in the form, whitelisted to <code>auth_type</code>, <code>hosts</code>, <code>cloud_id</code>, <code>username</code>, <code>password</code>, <code>api_key</code> and <code>index_prefix</code>. It answers 200 when <code>Webkul\\Product\\Enums\\SearchEngineStatusEnum::isUsable()</code> and 422 otherwise, with one of <code>available</code>, <code>unreachable</code>, <code>unauthorized</code>, <code>incompatible</code> or <code>misconfigured</code>. <code>SearchEngineAvailability</code> caches the verdict for five minutes under <code>search_engines.{engine}.availability</code>; the About page and the configuration page read that cache.</p><h2 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h2><p>The Elasticsearch indexer (<code>Webkul\\Product\\Helpers\\Indexers\\ElasticSearch</code>) writes one index per channel and locale, named by <code>ElasticSearchEngine::formatIndexName($channelCode, $localeCode)</code> as <code>{prefix}products_{channel}_{locale}_index</code>, and includes a <code>category_name</code> field built from the product&#39;s categories.</p><p>Indexing happens through two queued jobs that delegate to <code>SearchEngineManager::indexer()</code>:</p><table tabindex="0"><thead><tr><th>Job</th><th>Dispatched by</th></tr></thead><tbody><tr><td><code>Webkul\\Product\\Jobs\\Search\\IndexProducts</code></td><td>The product listener: dispatched on its own after create, and as the last link of a <code>Bus::chain</code> after the inventory and price index jobs after update; also by the product importer</td></tr><tr><td><code>Webkul\\Product\\Jobs\\Search\\DeleteProducts</code></td><td>The product listener before delete, and the importer</td></tr></tbody></table><p>On 2.4 these are <code>Jobs\\ElasticSearch\\UpdateCreateIndex</code> and <code>DeleteIndex</code>, each of which re-checks the engine setting inline.</p><p>A full rebuild is done from the console:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> indexer:index</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type=search</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode=full</span></span></code></pre></div><p><code>search</code> only runs when an external engine is enabled and only in <code>full</code> mode; there is no selective search reindex. On 2.4 the type is <code>elastic</code>. Run it after enabling Elasticsearch on an existing catalog, after changing <code>index_prefix</code>, and after the upgrade to the development version, whose index mapping added <code>category_name</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../performance/configure-elasticsearch.html">Configure Elasticsearch</a> — installing the cluster and pointing Bagisto at it.</li><li><a href="./understanding-indexers.html">Understanding Indexers</a> — the flat, price and inventory indexers that feed search.</li><li><a href="./queue-jobs-scheduling.html">Queue, Jobs &amp; Scheduling</a> — running the indexing jobs on a worker.</li></ul>`,35)]))}const k=s(n,[["render",d]]);export{g as __pageData,k as default};
